import { copyFileSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, it } from "vitest";
import { DurableEffectLedger } from "../src/durable-effect-ledger.js";

// Fixture generated by baseline 8b74b8f DurableEffectLedger public prepare/settle APIs, not manually inserted rows.
it("expands the legacy ledger without relabeling or losing accepted Weixin effects", () => {
  const directory = mkdtempSync(join(tmpdir(), "feishu-effects-"));
  const path = join(directory, "effects.sqlite");
  copyFileSync(new URL("./fixtures/channel-legacy-effects.sqlite", import.meta.url), path);
  let ledger = new DurableEffectLedger(path);
  try {
    expect(ledger.listByOperation("legacy-operation")).toEqual([{
      attemptId: "legacy-attempt", operationId: "legacy-operation", accountId: "old-bot", target: "owner@im.wechat",
      kind: "weixin_text", state: "accepted", createdAt: 1800000000000, settledAt: 1800000000000,
    }]);
    ledger.prepare({ attemptId: "feishu-attempt", operationId: "feishu-operation", accountId: "feishu.account", target: `feishu.${"a".repeat(64)}`, kind: "feishu_text" });
    ledger.settle("feishu-attempt", "unknown");
    ledger.close(); ledger = new DurableEffectLedger(path);
    expect(ledger.listByOperation("feishu-operation")).toMatchObject([{ kind: "feishu_text", state: "unknown", target: `feishu.${"a".repeat(64)}` }]);
    expect(ledger.retrySafety("legacy-attempt")).toBe("unsafe");
    expect(ledger.retrySafety("feishu-attempt")).toBe("unsafe");
  } finally { ledger.close(); rmSync(directory, { recursive: true, force: true }); }
});

// Generated by 2f74c89 public APIs: the intermediate schema already accepts feishu_text, but not media.
it("expands the text-only Feishu ledger while preserving both channels' settled records", () => {
  const directory = mkdtempSync(join(tmpdir(), "feishu-media-effects-"));
  const path = join(directory, "effects.sqlite");
  copyFileSync(new URL("./fixtures/channel-feishu-text-effects.sqlite", import.meta.url), path);
  let ledger = new DurableEffectLedger(path);
  try {
    expect(ledger.listByOperation("legacy-operation")).toMatchObject([{
      kind: "weixin_text", state: "accepted", accountId: "old-bot", target: "owner@im.wechat", createdAt: 1800000000000,
    }]);
    expect(ledger.listByOperation("feishu-operation")).toMatchObject([{
      kind: "feishu_text", state: "unknown", accountId: "feishu.account", target: `feishu.${"a".repeat(64)}`, createdAt: 1800000000000,
    }]);
    ledger.prepare({ attemptId: "media-attempt", operationId: "media-operation", accountId: "feishu.account", target: `feishu.${"a".repeat(64)}`, kind: "feishu_media" });
    ledger.settle("media-attempt", "accepted");
    ledger.close(); ledger = new DurableEffectLedger(path);
    expect(ledger.listByOperation("media-operation")).toMatchObject([{ kind: "feishu_media", state: "accepted" }]);
    expect(ledger.retrySafety("legacy-attempt")).toBe("unsafe");
    expect(ledger.retrySafety("feishu-attempt")).toBe("unsafe");
    expect(ledger.retrySafety("media-attempt")).toBe("unsafe");
  } finally { ledger.close(); rmSync(directory, { recursive: true, force: true }); }
});
